// ── n8n Code Node: The Splitter ──
// Handles both formats:
//   Format 1: { prompt1: "...", prompt2: "..." }
//   Format 2: { A: { description: "..." }, B: { description: "..." }, C: { description: "..." } }

const newItems = [];
const items = $input.all();

for (const item of items) {
  const json = item.json;

  // FORMAT 2: A/B/C variant objects (from GPT-4o)
  for (const key of ['A', 'B', 'C', 'D', 'E']) {
    if (json[key] && typeof json[key] === 'object' && json[key].description) {
      const cleanText = json[key].description
        .replace(/^(visual|image|prompt\s?\d*|scene\s?\d*|option\s?\d*|concept\s?\d*|pattern interrupt)\s*[:.-]\s*/i, "")
        .replace(/^["']|["']$/g, "")
        .replace(/\*\*/g, "")
        .trim();

      if (cleanText.length > 5) {
        newItems.push({
          json: {
            ...json,
            cleanPrompt: cleanText,
            sourceField: key
          }
        });
      }
    }
  }

  // FORMAT 1: prompt1, prompt2, etc. (legacy)
  if (newItems.length === 0) {
    for (const key of Object.keys(json)) {
      if (key.toLowerCase().startsWith('prompt') && typeof json[key] === 'string') {
        let cleanText = json[key]
          .replace(/^(visual|image|prompt\s?\d*|scene\s?\d*|option\s?\d*|concept\s?\d*|pattern interrupt)\s*[:.-]\s*/i, "")
          .replace(/^["']|["']$/g, "")
          .replace(/\*\*/g, "")
          .trim();

        if (cleanText.length > 5) {
          newItems.push({
            json: {
              ...json,
              cleanPrompt: cleanText,
              sourceField: key
            }
          });
        }
      }
    }
  }
}

if (newItems.length === 0) {
  return items.map(item => ({ json: { ...item.json, cleanPrompt: "ERROR: No valid prompt fields found in input." }}));
}

return newItems;

// Get aggregated items
const raw = $input.first().json;
const aggregatedData = raw.data || [raw];

if (!aggregatedData || aggregatedData.length === 0) {
  return [{ json: { "Ad Sets": "Error - No Data", "Status": "Failed", "Error": "No aggregated image data found" } }];
}

// Extract URLs from each fal.ai image response
const urls = [];
for (const item of aggregatedData) {
  const url = item.images?.[0]?.url || null;
  if (url) urls.push(url);
}

// Get metadata from first item
const first = aggregatedData[0] || {};
const firstImg = first.images?.[0] || {};

const output = {
  "Ad Sets": "Generated " + new Date().toISOString().split('T')[0],
  "A": urls[0] || null,
  "B": urls[1] || null,
  "C": urls[2] || null,
  "Seed": first.seed || null,
  "Width": firstImg.width || 1024,
  "Height": firstImg.height || 1024,
  "Model": "fal-ai/flux/dev",
  "Status": urls.length > 0 ? "Generated" : "Failed",
  "Prompt Used": first.prompt || null
};

return [{ json: output }];

const results = [];

for (const item of $input.all()) {
  try {
    let rawText;

    // PATH 1: The "Deep Nested" Output (This is what your screenshot shows)
    if (item.json.output && item.json.output[0] && item.json.output[0].content && item.json.output[0].content[0].text) {
      rawText = item.json.output[0].content[0].text;
    }
    // PATH 2: Simple Text (Simplify Output = ON)
    else if (item.json.text) {
      rawText = item.json.text;
    } 
    // PATH 3: Standard Content (Simplify Output = OFF)
    else if (item.json.content && item.json.content[0] && item.json.content[0].text) {
      rawText = item.json.content[0].text;
    }
    // PATH 4: Chat Message
    else if (item.json.message && item.json.message.content) {
      rawText = item.json.message.content;
    }

    if (!rawText) throw new Error("Could not find any text in the OpenAI output.");

    // CLEANUP: Remove markdown (```json)
    const cleanJson = rawText.replace(/```json/g, "").replace(/```/g, "").trim();

    // PARSE: Turn text into data
    const parsedData = JSON.parse(cleanJson);

    results.push({
      json: parsedData
    });

  } catch (error) {
    results.push({
      json: {
        error: "PARSING FAILED: " + error.message,
        debug_input: item.json
      }
    });
  }
}

return results;

